    ('f90d7650deb505f99cc5fc109b784406', '[[11.125, 75.625], [-7.337, 72.363]]'),
    ('f98f0d09d05ffb5392a36b5e5ace10c2', '[[35.963, -5.362], [35.9352, -4.9033], [37.375, 6.375], [37.375, 12.875], [37.125, 13.125], [31.375, 29.625]]'),
    ('f99f5564b3698050b999dad079059117', '[[51.469, 3.531], [51.5375, 3.4375], [52.875, 4.125], [57.875, 9.125], [57.875, 10.875], [55.375, 13.375], [55.375, 14.375], [55.9957, 16.0426], [56.2625, 16.5375], [58.1875, 18.8625], [59.8576, 21.4064], [60.2375, 21.7625], [60.2875, 21.9875], [60.388, 22.088]]'),
