    ('fcc6526cf1d424821b56b057e2e4602c', '[[-7.212, 112.863], [-7.1875, 112.8625], [-7.3226, 113.4678], [-7.875, 115.125], [-8.125, 115.625], [-8.375, 115.875], [-24.375, 113.125], [-25.5125, 112.9125], [-26.2875, 112.9875], [-31.7488, 115.2488], [-32.1375, 115.5875], [-32.125, 115.625]]'),
