    ('fd482ebcdefbc381828710e89b89f943', '[[30.125, 121.875], [30.6875, 122.5375], [33.6625, 126.4625], [34.6225, 128.1048], [34.7375, 128.2625], [34.8625, 128.3625], [34.863, 128.288]]'),
    ('fd9ccddca6554ab14ca698274d5b1471', '[[23.375, -82.375], [23.2625, -80.5625], [22.875, -76.625], [20.375, -74.125], [20.1625, -74.1375], [18.375, -74.625], [17.875, -74.125], [17.375, -71.375], [18.2625, -69.9875], [18.4375, -69.9125], [18.412, -69.887]]'),
    ('fde57c7ef49f150373cbb63fbddcea27', '[[63.875, -52.125], [63.2375, -51.4875], [61.125, -49.125], [60.625, -48.375], [59.8125, -44.1125], [59.7875, -43.7875], [59.846, -42.9757], [58.8626, -4.0354], [58.9375, -3.2625], [58.8875, -3.1125], [57.875, 7.125], [57.875, 10.875], [55.375, 13.375], [55.375, 14.375], [57.875, 22.375], [57.625, 23.125], [57.063, 23.938]]'),
