create function pg_temp.rev_0441(p jsonb) returns jsonb language sql immutable as $r$
  select jsonb_agg(t.x order by t.i desc) from jsonb_array_elements(p) with ordinality t(x, i)
$r$;

create function pg_temp.nm_0441(p jsonb) returns numeric language sql stable as $n$
  select sum((x ->> 'nm')::numeric) from jsonb_array_elements(voyage.segments_from_course(p)) x
$n$;

-- 0440's one step, with what 0440 left out: a navy patrol's frozen pieces (0331: public.cargo_circuit_plan's
-- legs, the same pieces a cargo circuit freezes) and the coast courses (0400: public.npc_coast_courses).
create function pg_temp.clear_0441() returns jsonb language plpgsql as $c$
declare
  v_lanes int;
  v_stops int;
  v_coast int;
  v_legs  int := 0;
  v_patrol int := 0;
  v_memo  int;
  v_pairs jsonb;
  l       record;
  m       record;
  v_txt   text;
begin
  -- The pieces of every replaced lane and coast course, either way round, old and new.
  select coalesce(jsonb_agg(jsonb_build_array(o.old_inner, o.new_inner)), '[]'::jsonb) into v_pairs
    from (select distinct trim(both '[]' from voyage.segments_from_course(q.c)::text) as old_inner,
                          trim(both '[]' from voyage.segments_from_course(q.n)::text) as new_inner
            from (select c.course as c, f.course as n
                    from (select course from public.npc_courses union select course from public.npc_coast_courses) c
                    join pg_temp.fix_0441() f on md5(c.course::text) = f.old_md5
                  union all
                  select pg_temp.rev_0441(c.course), pg_temp.rev_0441(f.course)
                    from (select course from public.npc_courses union select course from public.npc_coast_courses) c
                    join pg_temp.fix_0441() f on md5(c.course::text) = f.old_md5) q) o;
  for l in select 'cargo' as k, g.circuit_id as id, g.ord, g.segments::text as t from public.cargo_circuit_legs g
           union all
           select 'patrol', n.station_id, n.ord, n.segments::text from public.navy_patrol_legs n loop
    v_txt := l.t;
    for m in select e ->> 0 as old_inner, e ->> 1 as new_inner from jsonb_array_elements(v_pairs) e loop
      if strpos(v_txt, m.old_inner) > 0 then
        v_txt := replace(v_txt, m.old_inner, m.new_inner);
      end if;
    end loop;
    if v_txt <> l.t then
      if l.k = 'cargo' then
        update public.cargo_circuit_legs g
           set segments = v_txt::jsonb,
               nm = (select sum((x ->> 'nm')::numeric) from jsonb_array_elements(v_txt::jsonb) x)
         where g.circuit_id = l.id and g.ord = l.ord;
        v_legs := v_legs + 1;
      else
        update public.navy_patrol_legs n
           set segments = v_txt::jsonb,
               nm = (select sum((x ->> 'nm')::numeric) from jsonb_array_elements(v_txt::jsonb) x)
         where n.station_id = l.id and n.ord = l.ord;
        v_patrol := v_patrol + 1;
      end if;
    end if;
  end loop;

  update public.npc_courses c set course = f.course, nm = pg_temp.nm_0441(f.course)
    from pg_temp.fix_0441() f where md5(c.course::text) = f.old_md5;
  get diagnostics v_lanes = row_count;

  update public.npc_coast_courses c set course = f.course, nm = pg_temp.nm_0441(f.course)
    from pg_temp.fix_0441() f where md5(c.course::text) = f.old_md5;
  get diagnostics v_coast = row_count;

  update public.standing_route_stops s set course = f.course, course_nm = pg_temp.nm_0441(f.course)
    from pg_temp.fix_0441() f where md5(s.course::text) = f.old_md5;
  get diagnostics v_stops = row_count;

  insert into public.npc_course_zones_memo (course_md5, zones)
  select distinct on (k.h) k.h, k.zones
    from (select md5(f.course::text) as h, public.course_zones(f.course) as zones from pg_temp.fix_0441() f
          union all
          select md5(pg_temp.rev_0441(f.course)::text), public.course_zones(f.course) from pg_temp.fix_0441() f) k
   order by k.h
  on conflict (course_md5) do nothing;
  get diagnostics v_memo = row_count;

  return jsonb_build_object('lanes', v_lanes, 'stops', v_stops, 'coast', v_coast, 'cargo_legs', v_legs, 'patrol_legs', v_patrol, 'memo', v_memo);
end
$c$;

-- ── 4. SELF-ASSERT, on a probe that is rolled back ─────────────────────────────────────────────
do $$
declare
  v_join  numeric := public.wc_num('course_join_nm');
  v_bad   text;
  v_old   jsonb;
  v_new   jsonb;
  v_old2  jsonb;
  v_new2  jsonb;
  v_nat   uuid;
  v_circ  bigint;
  v_station bigint;
  v_port  uuid;
  v_got   jsonb;
  v_want  jsonb;
  v_res   jsonb;
begin
  -- (a) THE RASTER: every charted cell is water, and each charted channel lists exactly its cells.
  select string_agg(c.k::text, ' ') into v_bad
    from (values (222493), (279203), (279204), (288799), (290240), (291680)) c(k), public.sea_raster r
   where r.id = 1 and get_bit(r.cells, c.k * r.bits_per_cell) <> 1;
  if v_bad is not null then
    raise exception '0441 self-assert FAIL: charted cell(s) not water: %', v_bad;
  end if;
  if (select count(*) from voyage.channels c where c.id in ('corfu', 'western-scheldt', 'tsugaru') and jsonb_array_length(c.carved_cells) = c.opens_land) <> 3 then
    raise exception '0441 self-assert FAIL: a charted channel is missing from voyage.channels';
  end if;

  -- (b) THE CORFU CONTROL, AFTER: the same course, every sample checked (no approach slack), is water.
  if voyage.path_refusal('[[39.613,19.963],[39.7,19.96],[39.74,19.975],[39.785,19.968],[39.83,19.93],[39.92,19.85],[39.97,19.72]]'::jsonb, 39.613, 19.963, 39.97, 19.72, 0, 0, 0) is not null then
    raise exception '0441 self-assert FAIL: the Corfu control is still refused: %',
      voyage.path_refusal('[[39.613,19.963],[39.7,19.96],[39.74,19.975],[39.785,19.968],[39.83,19.93],[39.92,19.85],[39.97,19.72]]'::jsonb, 39.613, 19.963, 39.97, 19.72, 0, 0, 0);
  end if;

  -- (c) THE ROADS: every changed harbour is reached from the point this file measured, by the rule and by
  --     the table, and the helper line is the distance (gc(quay, roads) = snap_nm).
  select string_agg(v.code, ' ') into v_bad
    from (values
      ('ALG', 36.813::numeric, 3.113::numeric),
      ('AMB', -3.762::numeric, 128.238::numeric),
      ('ANC', 43.638::numeric, 13.588::numeric),
      ('ANG', 38.613::numeric, -27.287::numeric),
      ('BAN', 5.638::numeric, 95.288::numeric),
      ('BAS', 26.963::numeric, 56.413::numeric),
      ('BRI', 13.063::numeric, -59.662::numeric),
      ('CEU', 35.888::numeric, -5.237::numeric),
      ('CHS', 38.363::numeric, 25.938::numeric),
      ('CID', 14.863::numeric, -23.612::numeric),
      ('CON', -36.662::numeric, -73.037::numeric),
      ('COR', 39.613::numeric, 19.963::numeric),
      ('DGA', -7.337::numeric, 72.363::numeric),
      ('DIU', 20.662::numeric, 70.988::numeric),
      ('DJE', 33.938::numeric, 10.863::numeric),
      ('FLO', 39.438::numeric, -31.088::numeric),
      ('FNC', 32.612::numeric, -16.962::numeric),
      ('GAL', 5.988::numeric, 80.188::numeric),
      ('GIB', 35.963::numeric, -5.362::numeric),
      ('GOT', 32.713::numeric, 128.913::numeric),
      ('HAD', 12.688::numeric, 53.988::numeric),
      ('HAG', 13.538::numeric, 144.713::numeric),
      ('HOR', 26.963::numeric, 56.413::numeric),
      ('INC', 37.188::numeric, 126.462::numeric),
      ('JAF', 9.563::numeric, 79.963::numeric),
      ('JEJ', 33.563::numeric, 126.513::numeric),
      ('KUP', -10.388::numeric, 123.563::numeric),
      ('LGA', -0.262::numeric, 104.663::numeric),
      ('LPA', 28.138::numeric, -15.362::numeric),
      ('MAC', 22.188::numeric, 113.613::numeric),
      ('MAN', 26.287::numeric, 50.563::numeric),
      ('MAT', 41.363::numeric, 140.113::numeric),
      ('MLE', 4.238::numeric, 73.488::numeric),
      ('MOK', 34.788::numeric, 126.213::numeric),
      ('MWY', 28.162::numeric, -177.362::numeric),
      ('NAH', 26.263::numeric, 127.638::numeric),
      ('NEW', 40.538::numeric, -73.812::numeric),
      ('OSA', 34.338::numeric, 134.988::numeric),
      ('PAL', 38.163::numeric, 13.413::numeric),
      ('PLM', 39.512::numeric, 2.638::numeric),
      ('PLO', -20.112::numeric, 57.438::numeric),
      ('PON', 37.688::numeric, -25.662::numeric),
      ('PRT', 9.563::numeric, -79.712::numeric),
      ('PTT', 6.913::numeric, 101.188::numeric),
      ('PUS', 68.512::numeric, 51.513::numeric),
      ('RHO', 36.438::numeric, 28.287::numeric),
      ('RIG', 57.063::numeric, 23.938::numeric),
      ('SAK', 34.338::numeric, 134.988::numeric),
      ('SAO', 0.337::numeric, 6.788::numeric),
      ('SGO', 18.412::numeric, -69.887::numeric),
      ('STG', 32.388::numeric, -64.613::numeric),
      ('STO', 59.188::numeric, 18.488::numeric),
      ('SUR', -7.212::numeric, 112.863::numeric),
      ('TAL', 59.537::numeric, 24.737::numeric),
      ('TAN', 35.838::numeric, -5.812::numeric),
      ('TEN', 28.463::numeric, -16.187::numeric),
      ('TON', 34.863::numeric, 128.288::numeric),
      ('TOR', 62.013::numeric, -6.663::numeric),
      ('TOU', 43.063::numeric, 5.988::numeric),
      ('TRA', 41.063::numeric, 39.713::numeric),
      ('TRP', 32.963::numeric, 13.288::numeric),
      ('TSU', 34.188::numeric, 129.338::numeric),
      ('TUR', 60.388::numeric, 22.088::numeric),
      ('VAR', 70.363::numeric, 31.163::numeric),
      ('VIS', 57.663::numeric, 18.213::numeric),
      ('VLL', 35.938::numeric, 14.563::numeric),
      ('WIL', 12.063::numeric, -68.937::numeric),
      ('ZAK', 37.887::numeric, 20.788::numeric),
      ('ZAN', -6.162::numeric, 39.138::numeric)
         ) v(code, lat, lon)
    join public.ports p on p.code = v.code
    join public.sea_reaches sr on sr.port_id = p.id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) w
   where w.lat <> v.lat or w.lon <> v.lon or sr.roadstead_lat <> v.lat or sr.roadstead_lon <> v.lon
      or abs(sr.snap_nm - voyage.gc_distance_nm(p.lat::float8, p.lon::float8, v.lat::float8, v.lon::float8)::numeric) > 0.001;
  if v_bad is not null then
    raise exception '0441 self-assert FAIL: these roadsteads are not what this file measured: %', v_bad;
  end if;
  -- the owner's own harbour: Hadibu is reached from the water off Socotra's north shore, not from its quay.
  if not exists (select 1 from public.sea_reaches sr join public.ports p on p.id = sr.port_id
                  where p.code = 'HAD' and sr.roadstead_lat = 12.688 and sr.roadstead_lon = 53.988 and sr.snap_nm > 0) then
    raise exception '0441 self-assert FAIL: Hadibu is not reached from its drawn roadstead';
  end if;

  -- (d) THE SERVER'S LAW: every new course is raster water as cmd.do_sail judges a roads-to-roads course.
  select string_agg(f.old_md5 || ': ' || r.ref, '; ') into v_bad
    from pg_temp.fix_0441() f
   cross join lateral (select voyage.path_refusal(f.course,
                                (f.course -> 0 ->> 0)::numeric, (f.course -> 0 ->> 1)::numeric,
                                (f.course -> -1 ->> 0)::numeric, (f.course -> -1 ->> 1)::numeric, v_join, 25, 25) as ref) r
   where r.ref is not null;
  if v_bad is not null then
    raise exception '0441 self-assert FAIL: a re-sailed course is refused by voyage.path_refusal: %', left(v_bad, 2000);
  end if;

  -- (e) THE PROBE: a cargo circuit of its own whose one leg is two replaced lanes, the second read
  --     backwards. After the step its leg must be exactly the two new lanes' pieces, and no lane or
  --     route stop may still hold a replaced course. Rolled back whole.
  begin
    select c.course, f.course into v_old, v_new
      from public.npc_courses c join pg_temp.fix_0441() f on md5(c.course::text) = f.old_md5 order by f.old_md5 limit 1;
    select c.course, f.course into v_old2, v_new2
      from public.npc_courses c join pg_temp.fix_0441() f on md5(c.course::text) = f.old_md5 order by f.old_md5 desc limit 1;
    if v_old is not null then
      v_nat := (select g.nation_id from public.great_powers g order by g.nation_id limit 1);
      v_port := (select p.id from public.ports p where p.kind = 'HARBOUR' order by p.code limit 1);
      insert into public.cargo_circuits (nation_id, start_port) values (v_nat, v_port) returning id into v_circ;
      insert into public.cargo_circuit_legs (circuit_id, ord, to_port, nm, segments)
      values (v_circ, 1, v_port, 1, voyage.segments_from_course(v_old) || voyage.segments_from_course(pg_temp.rev_0441(v_old2)));
      -- and a navy station's patrol leg of the same two lanes, when the world has a station
      v_station := (select x.id from public.navy_stations x order by x.id limit 1);
      if v_station is not null then
        insert into public.navy_patrol_legs (station_id, ord, to_port, nm, segments)
        values (v_station, 9999, v_port, 1, voyage.segments_from_course(v_old) || voyage.segments_from_course(pg_temp.rev_0441(v_old2)));
      end if;
      v_res := pg_temp.clear_0441();
      v_got := (select g.segments from public.cargo_circuit_legs g where g.circuit_id = v_circ and g.ord = 1);
      v_want := voyage.segments_from_course(v_new) || voyage.segments_from_course(pg_temp.rev_0441(v_new2));
      if v_got is distinct from v_want then
        raise exception '0441 self-assert FAIL: the probe cargo leg was not re-cut to the new lanes (% pieces, % wanted)',
          jsonb_array_length(v_got), jsonb_array_length(v_want);
      end if;
      if exists (select 1 from public.npc_courses c join pg_temp.fix_0441() f on md5(c.course::text) = f.old_md5)
         or exists (select 1 from public.npc_coast_courses c join pg_temp.fix_0441() f on md5(c.course::text) = f.old_md5)
         or exists (select 1 from public.standing_route_stops s join pg_temp.fix_0441() f on md5(s.course::text) = f.old_md5) then
        raise exception '0441 self-assert FAIL: a lane, a coast course or a route stop still holds a replaced course after the step';
      end if;
      if v_station is not null and (select n.segments from public.navy_patrol_legs n where n.station_id = v_station and n.ord = 9999) is distinct from v_want then
        raise exception '0441 self-assert FAIL: the probe patrol leg was not re-cut to the new lanes';
      end if;
      -- a coast course re-sailed round the land is read backwards whole by public.npc_coast_legs (hunk 2)
      select string_agg(a.code || '->' || b.code, ' ') into v_bad
        from public.npc_coast_courses c join public.ports a on a.id = c.from_port join public.ports b on b.id = c.to_port
       where jsonb_array_length(c.course) > 2
         and not exists (select 1 from public.npc_coast_courses d where d.from_port = c.to_port and d.to_port = c.from_port)
         and not exists (select 1 from public.npc_known_legs(c.to_port) k where k.to_port = c.from_port)
         and (select l.course from public.npc_coast_legs(c.to_port) l where l.to_port = c.from_port) is distinct from pg_temp.rev_0441(c.course);
      if v_bad is not null then
        raise exception '0441 self-assert FAIL: these coast courses are not read backwards whole: %', v_bad;
      end if;
    end if;
    raise exception using errcode = 'ZX441', message = coalesce(v_res, '{}'::jsonb)::text;
  exception when sqlstate 'ZX441' then
    raise notice '0441 probe (rolled back): %', sqlerrm;
  end;
end
$$;

-- ── 5. THE STEP, for real ────────────────────────────────────────────────────────────────────────
do $$
declare
  v_res jsonb := pg_temp.clear_0441();
begin
  if exists (select 1 from public.npc_courses c join pg_temp.fix_0441() f on md5(c.course::text) = f.old_md5)
     or exists (select 1 from public.npc_coast_courses c join pg_temp.fix_0441() f on md5(c.course::text) = f.old_md5)
     or exists (select 1 from public.standing_route_stops s join pg_temp.fix_0441() f on md5(s.course::text) = f.old_md5) then
    raise exception '0441 FAIL: a lane, a coast course or a route stop still holds a replaced course';
  end if;
  raise notice '0441 self-assert ok: THE STRAITS ARE OPEN AND THE ROADS ARE WATER. 6 charted cell(s) open (the Corfu control refused before, water after); 69 roadstead(s) on the water, each what voyage.water_roadstead answers (Hadibu off its quay); 570 course(s) re-sailed, every one raster water by voyage.path_refusal; the probe cargo leg re-cut and rolled back. Rewritten: %', v_res;
end
$$;
